package com.coding2.the.max.petstore.order.model;

import java.time.LocalDate;

import org.springframework.data.annotation.Id;
import org.springframework.data.relational.core.mapping.Column;
import org.springframework.data.relational.core.mapping.Table;

import lombok.Data;

/**
 * A horse tracked by the store. Its ID is generated by the database.
 */
@Data
@Table(name = "horse", schema = "petstore")
public class Horse {
  @Id
  @Column(value = "horse_id")
  private Long horseId;

  @Column(value = "name")
  private String name;

  @Column(value = "breed")
  private String breed;

  @Column(value = "birth_date")
  private LocalDate birthDate;

  @Column(value = "weight_kg")
  private Double weightKg;

  @Column(value = "stall_number")
  private String stallNumber;

  @Column(value = "notes")
  private String notes;
}
